UPDATE `user_state` SET `anime_json` = replace(replace(replace(replace(`anime_json`, CAST(X'E7BD91E69893E4BA91E99FB3E4B990' AS TEXT), '个人录入'), CAST(X'E7BD91E69893E4BA91' AS TEXT), '个人录入'), CAST(X'6D757369632E3136332E636F6D' AS TEXT), '个人录入'), CAST(X'4E657465617365' AS TEXT), '个人录入') WHERE `anime_json` LIKE '%' || CAST(X'E7BD91E69893E4BA91' AS TEXT) || '%' OR `anime_json` LIKE '%' || CAST(X'6D757369632E3136332E636F6D' AS TEXT) || '%' OR `anime_json` LIKE '%' || CAST(X'4E657465617365' AS TEXT) || '%';
